contract InvMutTest {
    C c;
    uint public calls;
    uint public fails;
    constructor(C _c) { c = _c; }
    function run(address from, address[] memory tos, uint[] memory vals, uint failAt) public returns (bool) {
        require(tos.length > 0);
        require(tos.length == vals.length);
        require(failAt < tos.length || failAt == type(uint).max);
        bool reverted;
        bool ok;
        calls = 0;
        fails = 0;
        failIndex = failAt;
        try c.transfer(from, address(this), tos, vals) returns (bool r) {
            reverted = false;
            ok = r;
        } catch {
            reverted = true;
        }
        if (failAt == type(uint).max) {
            assert(!reverted && ok && calls == tos.length && fails == 0);
        } else {
            assert(reverted && calls == failAt + 1 && fails == 1);
        }
        return ok;
    }
    uint public failIndex;
    fallback() external payable {
        calls++;
        if (calls - 1 == failIndex) {
            fails++;
            assembly {
                mstore(0x00, 0)
                return(0x00, 0x20)
            }
        }
        assembly {
            mstore(0x00, 1)
            return(0x00, 0x20)
        }
    }
    receive() external payable {}
}

