contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address tokenAddr, address to, uint amount) public payable {
        require(amount != type(uint256).max);
        require(to != address(0));

        // 1) Empty recipient list must revert.
        bool revertedEmpty;
        address[] memory noTos = new address[](0);
        uint[] memory noVs = new uint[](0);
        try c.transfer(from, address(this), noTos, noVs) {
            revertedEmpty = false;
        } catch {
            revertedEmpty = true;
        }

        // 2) A batch where the second transferFrom is rejected (amount == type(uint256).max,
        //    which the fallback below refuses) must make the whole transfer revert,
        //    even though the first recipient is valid.
        bool revertedFail;
        address[] memory tos = new address[](2);
        tos[0] = to;
        tos[1] = to;
        uint[] memory vs = new uint[](2);
        vs[0] = amount;
        vs[1] = type(uint256).max;
        try c.transfer(from, tokenAddr, tos, vs) {
            revertedFail = false;
        } catch {
            revertedFail = true;
        }

        // 3) Sanity: a fully valid batch succeeds and returns true.
        bool okReturned;
        uint[] memory vsOk = new uint[](2);
        vsOk[0] = amount;
        vsOk[1] = amount;
        okReturned = c.transfer(from, tokenAddr, tos, vsOk);

        assert(revertedEmpty && revertedFail && okReturned);
    }

    fallback(bytes memory data) external returns (bytes memory) {
        // Emulate transferFrom(address,address,uint256); reject when amount == type(uint256).max.
        uint256 amt;
        if (data.length >= 100) {
            assembly { amt := mload(add(data, 100)) }
        }
        require(amt != type(uint256).max, "transferFrom rejected");
        return abi.encode(true);
    }

    receive() external payable {}
}

