contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address to, uint v) public {
        // Both calls carry identical inputs; they can only differ in ordering effects.
        // Rule: reverting is determined by the destination set alone, and every
        // non-reverting call returns true.
        address[] memory tos = new address[](2);
        tos[0] = to;
        tos[1] = to;
        uint[] memory vs = new uint[](2);
        vs[0] = v;
        vs[1] = v;
        bool r1;
        try c.transfer(from, caddress, tos, vs) returns (bool ok1) {
            r1 = ok1;
        } catch {
            r1 = false;
        }
        address[] memory tos2 = new address[](2);
        tos2[0] = to;
        tos2[1] = to;
        uint[] memory vs2 = new uint[](2);
        vs2[0] = v;
        vs2[1] = v;
        bool r2;
        try c.transfer(from, caddress, tos2, vs2) returns (bool ok2) {
            r2 = ok2;
        } catch {
            r2 = false;
        }
        assert(r1 == r2 && (!r1 || r1));
    }
    receive() external payable {}
}

