contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address token, address[] memory tos, uint[] memory vs) public {
        // Rule 1: empty recipient list must revert.
        address[] memory none = new address[](0);
        uint[] memory noneV = new uint[](0);
        bool revertedEmpty;
        try c.transfer(from, token, none, noneV) { revertedEmpty = false; }
        catch { revertedEmpty = true; }
        assert(revertedEmpty);

        // Rule 2: with a non-empty list, a successful call always returns true;
        // a failing underlying transferFrom causes a revert.
        require(tos.length > 0);
        require(tos.length == vs.length);
        bool ok = true;
        bool returned;
        bytes memory ret;
        try c.transfer(from, token, tos, vs) returns (bool r) { returned = true; ok = r; }
        catch { returned = false; }
        assert(returned == false || ok == true);
        ret;
    }
    receive() external payable {}
}
